    expect(responses.map((response) => response.status).sort()).toEqual([201, 409]);
    const registrations = await app.get(DatabaseService).db.selectFrom('league.rosters').select(['id', 'season_team_id']).where('season_id', '=', season.id).where('player_id', '=', player.id).execute();
